    private static readonly FrozenDictionary<string, WarpDefinition[]> RenewalByMap = RathenaRenewalDefault
        .GroupBy(warp => warp.SourceMap, StringComparer.OrdinalIgnoreCase)
        .ToFrozenDictionary(group => group.Key, group => group.ToArray(), StringComparer.OrdinalIgnoreCase);
    private static readonly FrozenDictionary<string, WarpDefinition[]> EffectiveByMap = AthenaIroEffective
        .GroupBy(warp => warp.SourceMap, StringComparer.OrdinalIgnoreCase)
        .ToFrozenDictionary(group => group.Key, group => group.ToArray(), StringComparer.OrdinalIgnoreCase);

    internal static IReadOnlyList<WarpDefinition> GetForMap(string map, WarpLoadProfile profile) => profile switch
    {
        WarpLoadProfile.RathenaRenewalDefault => RenewalByMap.TryGetValue(MapName.NormalizeWorld(map), out var renewal) ? renewal : [],
        WarpLoadProfile.AthenaIroEffective => EffectiveByMap.TryGetValue(MapName.NormalizeWorld(map), out var effective) ? effective : [],
        _ => throw new ArgumentOutOfRangeException(nameof(profile)),
    };
